12	import { STORE_LOCATOR_IS_ENABLED } from '@salesforce/retail-react-app/app/constants';
13	import { getCommerceAgentConfig } from '@salesforce/retail-react-app/app/utils/config-utils';
14	import { useUiCopy } from 'app/hooks/useUiCopy';
15	import { MegaMenuOpenContext } from 'app/hooks/useMegaMenuOpenReporter';
16	import { useHeaderMenuExpandedState } from 'app/hooks/useHeaderMenuExpandedState';
17	import { DrawerMenuStateContext } from 'app/hooks/useDrawerMenuState';
18	import type { MenuExpandedState } from './headerTypes';
19	import { LeftBar } from './leftBar';
20	import { RightBar } from './rightBar';
21	
22	type HeaderProps = {
23	  children?: React.ReactNode;
24	  onMenuClick?: () => void;
25	  onLogoClick?: () => void;
26	  onMyAccountClick?: () => void;
27	  onWishlistClick?: () => void;
28	  onMyCartClick?: () => void;
29	  onStoreLocatorClick?: () => void;
30	  onAgentClick?: () => void;
31	  searchInputRef?: React.Ref<HTMLInputElement>;
32	  [key: string]: unknown;
33	};
34	
35	type NavLink = {
36	  name: string;
37	  path: string;
38	  icon: React.ComponentType<{ boxSize: number }>;
39	};
40	
41	type OneClickCheckoutConfig = {
42	  enabled?: boolean;
43	};
